import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷二十六","description":"周易經傳集解 - 周易經傳集解卷二十六","frontmatter":{"title":"周易經傳集解卷二十六","description":"周易經傳集解 - 周易經傳集解卷二十六"},"headers":[],"relativePath":"classics/jingchuan-jijie/027.md","filePath":"classics/jingchuan-jijie/027.md"}'),r={name:"classics/jingchuan-jijie/027.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷二十六",tabindex:"-1"},[n("周易經傳集解卷二十六 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷二十六","aria-label":"Permalink to “周易經傳集解卷二十六”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解卷二十六 ​震坎艮震宋林栗撰。序：卦曰：「主器者莫若長子，故受之以震。」震者，動也。震之成卦，「鼎」之變也。自「鼎」之「震」變，下卦「巽」、上卦「離」而成也。巽，長女也；離，中女也；而震則長男也。夫器之大者莫若鼎，有是器，必有以主之。長女、中女，皆非主器者也。主之者，其惟長男乎？故夫革有冶鑄之功，鼎有亨飪之用，非震則莫能受之矣。是故「鼎」之初六，特著其義曰：「得妾以其子，無咎。」而序則以「震」繼之，明主器之重也。天下者，大器也。一人元良，萬國以正。唐、虞禪，夏後、殷、周繼，其此之謂乎？或曰：「唐、虞之禪，傳諸人也，而取諸長子，何哉？」曰：易者，象也；象者，象此者也。謂之長子者，言其可以長人也。其子不足以長人，而天下之能長人者，莫如舜、禹，謂之長子，不亦可乎？震：亨。震來虩虩，笑言啞啞；震驚百里，不喪匕鬯。象曰：震，亨。「震來虩虩」，恐致福也。「笑言啞啞」，後有則也。「震驚百里」，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。下震上震，成卦曰「震」者，初為「震」，二為「艮」，三為「坎」，四又為「震」，純卦之義也，於「坎」、「離」辨之矣。艮，止也；「坎」，陷也。當震之時，止者皆動，陷者皆奮，是以謂之「震」也。震：亨。震來虩虩，笑言啞啞。震驚百里，不喪七鬯。何謂也？曰：「震」，動也，起也。為雷，為龍，為足，為長子，為東方之卦，皆亨之象也。而先儒訓「震」為懼，以為恐懼以致亨，則失之矣。夫動起而謂之震者，取諸雷震以為義也。而震之為懼者，因其震驚而取之也。震在雷，懼在物，雷何懼之有哉？詩云：「薄言震之，莫不震疊」是也。今直訓「震」為懼，而遂言恐懼以致亨，則是舍其主而議其賓矣。故「震」之諸爻，二陽，施震者也；其四陰，逼震者也。陽爻言「震」，為施震之義；陰爻言「震」，為遇震之辭，斯兩得之矣。「震來虩虩，笑言啞啞」，為施震者言之也，初九是也。「震驚百里，不喪七鬯」，為遇震者言之也，六五是也。二陽莫善於初九，四陰莫善於六五，故彖發明之。諸家解此卦，惟蘇氏得之。其說曰：「震之為道，以威達德者也。故可試而不可遂。試則養而無窮，遂則玩而不明。初九，試而不遂者也。以虩虩之震，而繼之以啞啞之笑，明其不常用也。惟其不常用，故二陽莫敢犯其鋒，皆以遁避而後免也。」其所以震物者，非以害之，欲其恐而致福也。有則者，言其不遂也。此論甚當。而「不喪七鬯」，初無其說。七鬯者，祭祀之物也。七以薦牲而升俎，鬯以灌地而求神。夫臨祭祀，事神祗，雖當平時，猶難於無失，況夫雷震之威，遠及百里，孰不忘其故常，失其所守，而乃能周旋於七鬯之事，不為震驚所變者，言其定也。故六五之辭曰「億無喪有事」。有事者，有事於上帝，有事於先王也。六五剛柔相濟，而得乎中行，故能度緩急之宜，審彼己之𫝑，雖臨大事，遭大變，可以奉宗廟、事神祗，而不喪其所守也。故子曰：震來虩虩，恐致福也；笑言啞啞，後有則也。震驚百里，驚遠而懼邇也。不喪匕鬯，可以守宗廟社稷，以為祭主也。今本衍一「出」字，號「不喪匕鬯」，一自疑「出」字是「鬯」字之誤耳。王弼曰：「威震百里，則可以不喪匕鬯。」此說非是。象曰：瀳雷，震，君子以恐懼修省。震為雷，重震為瀳雷。天下雷行，物與無妄。而君子以之「恐懼修省」者，詩所謂「敬天之怒，無敢戲豫」，論語所謂「迅雷風烈必變」是也。古者先雷三日，奮木鐸以令兆民，曰：「雷將發聲，有不戒其容止者，生子不備，必有兇災。」然則恐懼修省者，吉凶與民同患之意也。雜卦曰：「震，起也。」「震」之為卦，以雷之瀳至而成。其在六爻，以「震」之先後為義。「起」猶初也。「震」之初來，物莫不作；及其瀳至，則玩之矣。傳曰：「一鼓作氣，再而衰，三而竭。」是故震也者，天地之始也。「震」之二陽，初九為「起」，九四為「瀳」。初九有「虩虩」之威，而九四有「遂泥」之困者，先後之殊也。六二「躋於九陵」，六三行而「無眚」者，以初九之「虩虩」也。六五以「往」為「厲」，上六以「徵」為「兇」者，以九四之「遂泥」也。「震」之為起，斯其義歟！初九：震來虩虩，後笑言啞啞，吉。象曰：「震來虩虩」，恐致福也；「笑言啞啞」，後有則也。初九「震」以陽居剛，而在下卦之下，上無其應，而承於六二之「艮」，故曰：「震來虩虩，後笑言啞啞，吉。」蠅虎謂之「虩虩」之捕蠅，悤焉而至，「震」之來也似之。「啞啞」，喜笑之聲也，物得其所，則「笑言啞啞」，既「震」之後似之。無虩虩之威，則物不知畏；無啞啞之笑，則物不知懷。此初九之「震」所以有取於聖人也。彖舉其略，爻言其詳，所以然者，初九正而不失其時故也。其震物也，初無害之之心，欲其恐而致福也。其既震也，「載笑載言」，此所以為有則也。說者乃以為恐懼處震，則能保其安裕。若爾，則「笑言啞啞」，義既盡矣，何必言後又系之以「吉」乎？六二，震來厲，億喪貝，躋於九陵。勿逐，七日得。象曰：「震來厲」，乘剛也。六二，「艮」也，以陰居柔而在下卦之中，上無其應而乘初九之震，故曰「震來厲」。「厲」，危也。六二以至柔而乘至剛，當震之來，其危甚矣，故曰「億喪貝，躋於九陵」。「億」，度也；「躋」，升也；「貝」，資財也；「陵」，大阜也。二以陰居柔，故有「喪貝」之象。「艮」為山，故有「躋陵」之象。六二居中履正，度震之來，必喪其貝，故升高以避之。初九之「震」，警之而已，豈利其貝也哉？故曰：「勿逐，七日得。」以明初九之志不在於貝也，逐則遂喪之矣。「九陵」者，「艮」乘震之象；「七日」者，陰陽之一復也。聖人於陽爻明施震之方，於陰爻言遇震之道，示人著矣。故子曰：「震來厲，乘剛也。」六三，震蘇蘇，震行無眚。象曰：「震蘇蘇」，位不當也。六三上體為「坎」，下體為「艮」，以陰居剛而在下卦之上，連於初九而承於九四，二爻皆「震」也，故曰：「震蘇蘇，震行無眚」。兩言「震」者，在初九、九四之間也。「蘇」與「蘇」同，死而復生者謂之「蘇」。初九之來，二既避之，則三當其震，居不當位，體乎艮「坎」。「艮」，止也；「坎」，陷也。止而陷焉，不能以自出，而震有反生之象，是以謂之「蘇蘇」也。三止則遇初，行則遇四。初之「震虩虩」而不可犯，四之「震遂泥」而不足畏，是以六三行而「無眚」也。故子曰：「震蘇蘇，位不當也。」君子之所以行乎患難，威武不能屈者，當其位而已矣。九四：震遂泥。象曰：「震遂泥」，未光也。九四上體為「震」，下體亦為「震」，以陽居柔而在上卦之下，承於六五而乘乎六三，二爻皆「坎」，而三又「艮」也，故曰：「震遂泥。」「遂」字依荀本作「隊」，音墜。「泥」，水土相漸也。「艮」為土，「坎」為水，故有隊泥之象。九四不中，不當其位，震於既震之後，震之又震，可已而不已，陷於「坎」「艮」之中，是以謂之「隊泥」也。夫震也者，天之威也。震於此而動於彼，發越而光明者，動靜不失其時也。今也極其𫝑而反陷於泥，則失其所以為威矣。書曰：「德威惟畏，德明惟明。」有德之威，使民易避而難犯，怒之則懼，愛之則懷。若夫強暴之威，使民無所措手足，將以窮物而不知自窮。故六三行而「無眚」，六五億而「無喪」，上六「有言」而「無咎」者，為其隊泥而莫之畏也。故子曰：「震隊泥，未光也。」「震」，東方也，未出乎「坎」，所以為未光歟？六五：震往來，厲。億無喪，有事。象曰：「震往來厲」，危行也。其事在中，大無喪也。六五，「坎」也，以陰居剛而在上卦之中，下無其應，而乘九四之「震」，故曰：「震往來，厲。」初九之「震」，易避而難犯。為六二者，來則厲，往則安。九四之「震」，可已而不已，其志將有所利焉。為六五者，往而避之，則喪其貝；來而乘之，則逆其鋒。往來皆厲，則不動而已矣。故曰：「億無喪，有事。」六五之遇九四也，強弱足以相當，不若六二之遇初九，非其敵也。柔得尊位得中，而四為之難，度己之𫝑，力足以當之，而不至於有喪，則固其疆圉，靖其國家，以為民神之主，從容堂陛之間，潔其簠簋籩豆，奉其犧牲粢盛，以為宗廟社稷之薦，剛不至於犯難，柔不至於畏人，雖九四之強暴莫能加焉，此彖之所謂「可以為祭主」者也。故子曰：「震往來厲，危行也。其事在中，大無喪也。」危在於行，則在中為無喪矣。「師」之六三曰：「師或與屍，大無功也。」「大無功」雲者，謂有喪也。此言「大無喪」者，謂有功也。不言有功者，待其自至耳。六五之於九四，其𫝑雖足以相當，然陰之不逮陽必矣。苟可無喪，安能有功？左傳所謂「彼竭我盈，故克之」也。以逸待勞，以壯待老，以整待亂，其有功也，不亦宜乎？上六：震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。象曰：「震索索」，中未得也；雖兇無咎，畏鄰戒也。上六，「艮」也。以陰居柔，而在上卦之上，下無其應，而連於九四之「震」，故曰：「震索索，視矍矍，徵兇。」「索索」，氣不充也；「矍矍」，神不定也。「艮」為止，而當「震」之來，處非其位，不得乎中，故有「索索」、「矍矍」之象。然九四之「震」，不足以加於六五，其能以及上六乎？苟徵以避之，則四將乘虛而取其具矣。故曰：「震不於其躬，於其鄰，無咎。」「躬」，上六也；「鄰」，六五也。「震」之來也，不於我而於鄰，則徵而避之者過矣。上見五之不動以無喪，往來而皆厲，則亦將靜而待之，是以為「無咎」也，故曰：「婚媾有言。」八純之卦，上下敵應，無相與之義。其所稱「婚媾」者，於其本體而言之也。九四之於六五，有「婚媾」之道，而以其威加焉，故不之與。舍而求上六，上之與四，無相與之義，是以不免於「有言」也。夫六二、六五之於「震」為近，或億無喪而有事，或億有喪而避之，未嘗至於顛沛而失據也。六三、上六皆遠於「震」，而三至於「蘇蘇」，上至於「索索」者，謂其無主於中，遇物而自喪也。然初九以其威加於六三，行而避之，則可以「無眚」；而九四以其威加於上六，既不能勝而與之「婚媾」，猶不免於「有言」，明其「遂泥」而喪威之甚也。故子曰：「震索索，中未得也。」雖㓙無咎，畏鄰戒也。序卦曰：「震者，動也。物不可以終動，止之，故受之以艮。艮者，止也。」「艮」之成卦，震之反也。自「震」之「艮」，二五不動，四爻則易而成也。一陽在二陰之下，居非其所，欲無動，得乎？是以謂之「震」也。一陽在二陰之上，動將何往？欲無止，得乎？是以謂之「艮」也。「艮」者萬物之終，而「震」者萬物之始也。震反則為「艮」，「艮」反則為「震」。是故「震」兼虩虩啞啞之辭，而「艮」備時止時行之義。「震」以初九為「吉」，而九四為「遂泥」；「艮」以上九為吉，而九三為「薰心」，明「震」之不可終動，「艮」之不可終止也。艮其背，不獲其身；行其庭，不見其人，無咎。彖曰：「艮」，止也。時止則止，時行則行，動靜不失其時，其道光明。「艮其止」，止其所也。上下相應，不相與也。是以下「獲其身，行其庭，不見其人，無咎」也。下艮上「艮」。成卦曰「艮」者，初為艮，二為坎，三為震，四又為艮。「坎」，北方也；「震」，東方也。而「艮」則東北之卦，「坎」之所終，而「震」之所始也。「坎」不入乎「艮」，無以成萬物之終；震不出乎「艮」，無以成萬物之始。是故動以靜為本，行以正為基。今夫草木之生，人見其條達茂遂而已，不知其枝幹節葉已具於根荄脈縷之中。其本大者其末長，其源深者其流遠，其積厚者其施博，自然之理也。故曰：「夫乾，其靜也專，其動也直，是以大生焉。夫坤，其靜也翕，其動也闢，是以廣生焉。」然則當「艮」之時，苟不能止，無以為震動之資矣。易曰：「貞者，事之幹也。」又曰「終萬物始萬物者，莫盛乎艮」。其此之謂歟？故子曰：「時止則止，時行則行，動靜不失其時，其道光明。」日出乎震，則光明見矣。「艮其背，不獲其身，行其庭，不見其人，無咎。」何謂也？曰：「艮」之三晝，一陽在二陰之外，其形內向，有背面而立之象。因而重之，則前「艮」為「背」，而後「艮」為止於其背之象矣。故「艮」之諸爻，上九止於九三之後，「艮其背」也。下無其應，不獲其身也。庭，內外交際之地也。三四內外之交，庭之象也。九三為「震」，有反面外向之象，而動於群陰之中，是行其庭也。上無其應，是不見其人也。夫物近而不相得則兇，或害之，悔且吝。今也止於其背而不獲其身，可謂近而不相得矣。不見其人而行其庭，可謂或害之者矣。然而系之旡咎者，何哉？「艮」之時則然也。夫「艮」也者，萬物之所成終而所成始也。使上九「艮其背」而必獲其身，則是與之偕止而不知行也。九三行其庭而不見其人，則是與之偕動而不知靜也。故夫「艮」者，兼動靜之宜，備屈伸之理。當上九之時，可止而不得不止也；當九三之時，可行而不得不行也。此所謂「其道光明」者歟？孟子有言：「可以仕則仕，可以止則止，孔子也。」或曰：「二體皆艮也，反而視之，則皆震也。何以知上九當止，而九三當行乎？」曰：上九者，「艮」之終也，萬物歸根覆命之時也。萬物歸根覆命，而一陽之氣已動乎淵泉，則九三之象也。三之為震，出乎坎而不待反而後得之矣。故上九之辭曰：「敦艮吉。」九三之辭曰：「厲薰心。」明動靜之各有其時也。君子之道，或出或處，或默或語，無適無莫，惟義所在，亦若是而已。孔子曰：「微子去之，箕子為之奴，比干諫而死，商有三仁焉。」夫比干已死，而箕子又為之奴，可謂「艮其背」矣，而不能止微子之勿行，是謂「不獲其身」也。微子去商而歸周，可謂行其庭矣，而不能使箕子之勿留，是謂不見其人也。三人之行不同，而夫子同稱之曰「仁」，不敢少貶焉。夫有廢必有興，有終必有始。比干之死，與箕子之留，所以明君臣之義也；微子去之，所以明天人之歸，存社稷之計也，其何咎之有哉？故子曰：「艮其背，止其所也。上下敵應，不相與也。是以不獲其身，行其庭，不見其人，無咎也。」「艮其背」誤作「艮其止」，當依上文讀之。古者「背」「比」字通用，「比」字訛為「止」耳。背者，與人相違之地；北者，幽陰之所。當此而不止，則是失道而冥行也。夫八重卦皆敵應不相與，而獨言於「艮」者，謂其以止為義，則無復相與之意矣。然則不獲其身，不見其人，而可以咎之哉？書曰：「自靖，人自獻於先王，我不顧行遁。」此之謂也。象曰：兼山，「艮」，君子以思不出其位。「艮」為山，重卦為兼山，但取山象，艮止之義備矣。而取諸「兼山」者，明尊卑小大各有其位，介辨而可不亂也。自天子至於庶人，守其位則安，出其位則悖，是以君子思而不出也。君止於仁，臣止於忠，父止於慈，子止於孝；上不逼下，下不僭上；尊者制其略，卑者治其詳，皆不出其位之義也。雜卦曰：「艮，止也。」「艮」之為卦，以物之終始而成。其在六爻，以時止則止為義。今夫動者未嘗無止，止者末嘗無動，然天為動，地為止，何也？以其常者言之也。人受天地之中以生，參乎高厚之際，忽焉而動，倏焉而止，不可以一端而蔽之。欲言動靜屈伸之理，莫若近取諸身矣。是以「艮」之為爻，分配人之一身。人之一身，動靜之機，外系乎足，內系乎心。初六，「艮」也，足之位也；六四「艮」也，心之位也。心與足動，則身欲止不可得矣；心與足止，則身欲動不可得矣。然心止則足止矣，心止而足不止，則其動未可知也。故六四言「艮其身」，而初六但言「艮其趾」而已。易惟「鹹」、「艮」二卦純取於「身」，「鹹」之諸爻，感應以相與，而「艮」之諸爻，敵應不相與，然皆可以取譬於身，何也？「鹹」者，感也，感其心，然後能感人也。「艮」者，止也，止其心，然後能止其身也。是故以體分爻，然後有以見心之所在，心不可見，則「鹹」、「艮」之義廢矣。「鹹」之九四，心之所在也，故曰「朋從爾思」。思者，心之用也。「艮」之六四，心之所在也，故曰「艮其身」。總言身者，心為之君也。「鹹」之彖曰：「聖人感人心而天下和平。」「艮」之大象曰：「君子以思不出其徵」。皆所以發明其義也。若夫六二之「艮其腓」，九三之「艮其限」，六五之「艮其輔」，皆取象於身，以明心之所在也。自趾而上之，至五為輔矣，則上之為顛可知也。不取諸「顛」而言「敦艮」者，微其顯而闡其幽也。或曰：序卦「震動艮止也」，雜卦「震起艮止也」，二者之義有以異乎？曰：動止言其性也，起止言其時也。性也者，靜躁之謂也；時也者，始終之謂也。要其歸趣，則一而已。初六：艮其趾，無咎，利永貞。象曰：「艮其趾」，未失正也。初六，「艮」也，以陰居剛而在下卦之下，上無其應而承於六二之「坎」，故曰「艮其趾」。趾也者，體之至卑也。初居下而其數偶，故有趾之象焉。「艮其趾」則不行矣，又何咎之有哉？缺心而「艮其趾」，心苟欲動，非趾之能禁也，所謂系焉而止者歟？故曰：「利永貞。」貞猶固也，永以為貞，斯為善矣。子曰：「艮其趾」，末失正也。未之為言，不保其往云爾。「鹹」言「拇」，「艮」言「趾」，象其物宜也。六二：艮其腓，不拯其隨，其心不快。象曰：「不拯其隨」，未退聽也。六二，「坎」也，以陰居柔而在下卦之中，上無其應而承於九三之「震」，故曰「艮其腓」。「腓」，腨肉，下體之中也。二居中而數偶，故有腓之象焉。腓，塊然無能為者也，不「艮其趾」而「艮其腓」，趾苟欲動，非腓之所能禁也。故曰：「不拯其隨，其心不快。」「坎」為陷，故有「不拯」之象；為憂，為心病，故有「不快」之象。夫趾者，腓之所隨也。「鹹」之九三曰：「鹹其股，執其隨。」服之所隨者，腓也，故「鹹」之隨為「腓」。「艮」六二：「艮其腓，不拯其隨。」腓之所隨者，趾也，故「艮」之隨為「趾」。趾動而腓不能禁，趾陷而腓不能拯，其心安得而快乎？故子曰：「不拯其隨，未退聽也。」坎為耳，故有聽象。六二止之不得其所，欲其退聽，不亦難乎？九三：艮其限，列其夤，厲薰心。象曰：「艮其限」，危薰心也。九三上體為「震」，下體亦為「震」，以陽居剛而在下卦之上，上無其應，而介於六二、六四之間，二爻皆「坎」，而四又「艮」也，故曰「艮其限」。「限」，腰也，帶之所限也。上下二體於此乎分，是以謂之限也。九三上下之交，其數奇，其體震，反覆皆動，故有限之象焉。限也者，當吐納呼吸之衝，系俯仰屈伸之節，而下可以形格𫝑禁者也。故「列其夤，厲薰心」。「列」字依蓋本作「裂」。「裂」，絕也。「夤」，膂也。「薰」，蒸也。「裂其夤」者，其氣勿亂而絕其膂也。「薰其心」者，其氣鬱蒸而病其心也。內不「艮其心」，外不「艮其趾」，而「艮」諸腰限之間，𫝑不能止，則將裂絕其膂而危病其心，非直不快而已。故子曰：「艮其限，危薰心也。」朱氏按，古本「薰」或作「動」，今兩存之。「艮」之諸爻，惟九三不雜於柔，此彖之所謂「時行則行」者也。施「艮」於此，宜其危哉！六四，艮其身，無咎。象曰：「艮其身」，止諸躬也。六四上體為「艮」，下體為「坎」，以陰居柔，而在上卦之下，下無其應，而連於上九，乘乎九三，二爻皆「震」也，故曰「艮其身」。「身」也者，四肢百體之總名也。四肢百體合為一身，而聽命於心。心也者，身之主也，虛其中而為之宰也。下三爻施「艮」於一體，猶不能禁，而此獨能「艮其身」者，以心之所在故也。二言「不快」，三言「薰心」者，互發其辭也。四居上體之下，陰畫為虛，故有「心」之象焉。「艮」為止，「震」為動，以靜制動，是以謂之「艮其身」也。止之於心，則手足耳目無敢不聽，夫何咎之有哉？故子曰：「艮其身，止諸躬也。」不言「身」而言「躬」者，身猶伸也，躬猶恭也。身之所恭，其當心之處乎？或曰：子以六四陰畫虛，故有虛中之象。「鹹」之九四則剛實為也，亦謂之心，何哉？曰：「鹹」者，感也，心之動也；「艮」者，止也，心之靜也。靜則為虛，動則為實，聖人豈苟云乎哉？易曰：無思也，無為也，寂然不動，「艮」之心也。「感而遂通天下之故」，則「鹹」之九四當之矣。六五：艮其輔，言有序，悔亡。象曰：「艮其輔」，以中正也。六五，「艮」也。以陰居剛，而在上卦之中，下無其應，而承上九之「震」，故曰「艮其輔」。「輔」，口車也，虛其中以為出納者也。五居上卦之中，陰畫為虛，故有「輔」之象焉。「鹹」之「輔」在上，而「艮」之「輔」在五，則取其虛而已矣。輔也者，飲食之所自入，言語之所由出也。飲食以養其身，言語以道其意，未有能絕之者也。然則「艮其輔」雲者，豈將緘塞之而已？平謹其言語，節其飲食，斯之謂「艮」矣。故曰：「言有序，悔亡」。時然後言，則不失其序，而悔可亡也。夫「艮」之言止也，以陰居剛，不純乎靜，是以有「悔」。動靜語默，不失其時，是以「悔亡」也。故子曰：「艮其輔，以中正也。」以六居五，非「艮」之正，其以中為正者與？是故六四可以為心，而不可以為輔，六五可以為輔，而不可以為心，亦象其物宜也。體有動靜，而心有不動者存，此四之所以「無咎」，而五之所以「悔七」者歟！上九：敦艮，吉。象曰：「敦艮」之「吉」，以厚終也。上九，「震」也。以陽居柔，而在上卦之上，下無其應，而乘六五之「艮」，故曰「敦艮」。敦，厚也，益也，艮之至也。「臨」之上六，以益於六五，為「敦臨」；「復」之六五，以益於六四，為「敦復」。今艮之上九，次乎六五，剛柔殊惟，而謂之「敦艮」，何也？曰：取諸重卦而系之，猶震之九四，因初九之震，而有遂泥之象也。九三既已艮矣，上九又從而益之，彖之所謂「艮其背，不獲其身」者也。謂之「敦艮」，不亦宜乎？或曰：「子之言象，初六、六四艮也；九三、上九，震也。而易之，何哉？」曰：重卦六爻，無非艮也。初六、六四司艮之權，而所以艮者，九三、上九也。非艮乎陰，艮乎陽也。艮三索而得男，雖含震動之象，而當歸根覆命之時，止之又止，乃其所也，故曰「吉」。子曰：「敦艮之吉，以厚終也。」夫物不可以終動，亦不可以終止，故艮次震、「漸」、坎、「艮」，明屈信動靜，猶寒暑之相推也。上九艮之終，終則變矣，而系之「敦艮」矣。夫子又繼之以厚終之辭，何也？曰：震以初九為先，而九四為後。艮以上九為後，而九三為先。自下而上，自然之序也。然艮之先者，其震亦先，艮之後者，其震亦後，自然之理也。上九方「艮」而九三已震，則上之成終而三之成始也。「時止則止，時行則行」。方其止也，惟患其不固也；及其動也，惟患其不亟也。故止則如山，而動則如雷，易之道也。三在群陰之中，而上下皆「震」，其動也，孰能御之矣？上九之以厚終也，不亦善乎！周易經傳集解卷二十六",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
